INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'total_water_volume_m3', 'Gesamtwasservolumen des Naturteichs', 'Total water volume of the natural pool', 'number', 'm³', false, '§5, Tab. 4 / Tab. 5 / Tab. 6', 'Coverage block 3 (A-4/A-7): the reference quantity of the feed-rate rules ("% of the total water volume/day"); nothing in the encoding carried a volume before. Engineer input (the zones register carries areas and depths, not volumes).', 'verified_against_standard', 'Table 4 (Type III), Filter operation/warm water circulation during the swimming season: "operation of surface discharge depending on design · filter feed rate > 25% of the total water volume/day · filter operation > 12 h/day · maximum downtime 1 h" — Table 5 (Type IV): "filter feed rate > 80% of the total water volume/day · filter operation 24 h/day" — Table 6 (Type V): "filtration rate > 80% of the total water volume/day · filter operation 24 h/day"', 'FLL-Naturteich (EN 2023) printed p. 25–27 — §5, Tab. 4 / Tab. 5 / Tab. 6', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'total_water_volume_m3') AND w.code = 'FLLNT-06' AND s.code = 'FLL-Naturteich';
