SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'liner_on_concrete_base', 'Folie/Bahn auf ebenem, standfestem Untergrund aus Beton verlegt (faltenfrei gefordert)', 'Liner installed on a level, stable concrete subsoil (crease-free required)', 'boolean', NULL, false, '§9.3', 'Coverage block 3 (A-38): on concrete the liner must be crease-free; without concrete the printed crease tolerances apply (REQ-38, staged).', 'verified_against_standard', 'Synthetic and elastomer liners in visible areas: are to be installed crease-free on level and stable subsoil (e.g. made of concrete); if concrete has not been applied to the subsoil, creases with a height of up to 1.0 cm and a length of up to 2.0 m with a minimum distance of 2.0 m from each other can be tolerated. Creases are not permitted to cross over each other. These specifications apply to the natural pool when it is filled. Creases cannot hinder the use of maintenance equipment;', 'FLL-Naturteich (EN 2023) printed p. 42 — §9.3', NULL, NULL, NULL, 'sealing_type IN {''EPDM'', ''PVC''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
