INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'overflow_connected_water_surface_m2', 'Wasseroberfläche des an den Überlauf angeschlossenen Bereichs', 'Water surface of the area connected to the overflow weir', 'number', 'm²', false, '§10.3.1', 'Coverage block 3 (A-56 / B-1): the multiplier of the 150 l/m² rule is the inundated WATER SURFACE (plan area) of the connected area — single-area systems: the total water surface; multi-area: only the connected area. EQ-05 / REQ-33 currently multiply pool_underwater_surface (bottom + walls, App. 5) — wrong operand; the rewrite is 3b (staged).', 'verified_against_standard', 'A water reservoir is mandatory when using rigid overflow weirs. […] The usable volume of the splash water tank must be dimensioned so that at least 150 l per square metre can be provided to the inundated water surface. […] In the case of multi-area systems, only the water surface of the area to which the overflow weir is connected is taken into account.', 'FLL-Naturteich (EN 2023) printed p. 54–55 — §10.3.1', 'scalar', NULL, NULL, 'rigid_overflow_used == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'overflow_connected_water_surface_m2') AND w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich';
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'FLLNT-11-D3', 'feed_share_of_volume_pct = filter_feed_volume_per_day_m3 * 100 / total_water_volume_m3', ARRAY['filter_feed_volume_per_day_m3','total_water_volume_m3']::text[], 'feed_share_of_volume_pct', '%', '§5, Tab. 4 / Tab. 5 / Tab. 6', 'Coverage block 3 (A-4/A-7): feed share of the total water volume per day; total_water_volume_m3 lives on FLLNT-06 (cross-sheet input, like pool_underwater_surface in EQ-01/EQ-03).', 'verified_against_standard', 'Table 4 (Type III), Filter operation/warm water circulation during the swimming season: "operation of surface discharge depending on design · filter feed rate > 25% of the total water volume/day · filter operation > 12 h/day · maximum downtime 1 h" — Table 5 (Type IV): "filter feed rate > 80% of the total water volume/day · filter operation 24 h/day" — Table 6 (Type V): "filtration rate > 80% of the total water volume/day · filter operation 24 h/day"'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
COMMIT;
